def fibfib(n: int):
    memo = {0: 0, 1: 0, 2: 1}

    def helper(k):
        if k in memo:
            return memo[k]
        memo[k] = helper(k-1) + helper(k-2) + helper(k-3)
        return memo[k]

    return helper(n)

def cycpattern_check(a, b):
    if len(b) > len(a):
        return False
    b_len = len(b)
    for i in range(b_len):
        rotated = b[i:] + b[:i]
        if rotated in a:
            return True
    return False

import re

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def words_in_sentence(sentence):
    words = re.findall(r'\b\w+\b', sentence)
    filtered = [word for word in words if is_prime(len(word))]
    return ' '.join(filtered)

def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            total += num ** 2
        elif i % 4 == 0:
            total += num ** 3
    return total

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    if ' ' in txt or '\t' in txt or '\n' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for c in txt:
            if c.islower():
                if (ord(c) - ord('a')) % 2 == 1:
                    count += 1
        return count

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    if not nums:
        return []

    def digit_sum(x):
        return sum(int(d) for d in str(abs(x)))

    return sorted(enumerate(nums), key=lambda pair: (digit_sum(pair[1]), pair[0]))

